const withLogits = inputs.woeProfiles.map((p) => {
  const logit = 0.5 + (p.wAge * 0.8) + (p.wUtil * 1.4) + (p.wInq * 0.9) + (p.wLate * 1.6) + (p.lines * 0.05);
  return {
    id: p.id,
    logit: Math.round(logit * 1000) / 1000,
  };
});
return { logitProfiles: withLogits };
```

