  averageCreditScore: avgScore,
  approvedCount,
  totalCreditLimitAssigned: totalLimit,
  totalCapitalReservesCommitted: totalReserves,
  averageApprovedAprPct: avgApr,
  portfolioAcceptable: avgScore >= 600 && approvedCount >= 4,
};
```

